-- GIN index for JSONB containment queries (@>, ?, ?&, ?|)
-- jsonb_path_ops is smaller and faster but only supports @>
CREATE INDEX CONCURRENTLY IF NOT EXISTS {{index_name}}
  ON {{table_name}}
  USING GIN ({{jsonb_column}} jsonb_path_ops);

-- Containment query (hits jsonb_path_ops index)
EXPLAIN ANALYZE
SELECT *
FROM {{table_name}}
WHERE {{jsonb_column}} @> '{"status": "active"}'::jsonb;

